mapper.select:
SELECT sst.*, (SELECT sys_dict_item_name FROM sys_dict_item WHERE sys_dict_item_id = sst.sys_sms_template_category) sysSmsTemplateCategoryLabel FROM sys_sms_template sst WHERE sys_project_id = #{request.sysProjectId}
AND sys_sms_template_content LIKE CONCAT(#{request.sysSmsTemplateContent}, '%')
ORDER BY sst.sys_sms_template_sort
